package com.farika.soundflow;
import android.app.job.*;import android.app.Activity;import org.json.*;import java.util.*;import android.content.*;import android.net.*;import android.os.Build;
public final class AutoDownloads {
 private static final int PERIODIC=501,ONCE=502,RETRY=503;
 static boolean wifi(Context c){return c.getSharedPreferences("auto_download",0).getBoolean("wifi",true);}
 static void wifi(Context c,boolean value){c.getSharedPreferences("auto_download",0).edit().putBoolean("wifi",value).apply();JobScheduler js=c.getSystemService(JobScheduler.class);js.cancel(PERIODIC);js.cancel(ONCE);js.cancel(RETRY);schedule(c);retry(c);}
 static boolean allowed(Context c){ConnectivityManager cm=c.getSystemService(ConnectivityManager.class);NetworkCapabilities caps=cm.getNetworkCapabilities(cm.getActiveNetwork());return allowed(caps,cm.getActiveNetworkInfo(),wifi(c));}
 static boolean allowed(NetworkCapabilities caps,boolean wifiOnly){return caps!=null&&caps.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET)&&(!wifiOnly||caps.hasTransport(NetworkCapabilities.TRANSPORT_WIFI));}
 static boolean allowed(NetworkCapabilities caps,NetworkInfo info,boolean wifiOnly){if(allowed(caps,wifiOnly))return true;return wifiOnly&&caps!=null&&caps.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET)&&caps.hasTransport(NetworkCapabilities.TRANSPORT_VPN)&&info!=null&&info.isConnected()&&info.getType()==ConnectivityManager.TYPE_WIFI;}
 static String waitReason(Context c){ConnectivityManager cm=c.getSystemService(ConnectivityManager.class);NetworkCapabilities caps=cm.getNetworkCapabilities(cm.getActiveNetwork());if(caps==null||!caps.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET))return "Ожидание подключения к интернету. Очередь сохранена.";return wifi(c)?"Ожидание Wi-Fi: включено «Только Wi-Fi». Под VPN тип сети должен подтверждаться Android.":"Ожидание доступной сети. Очередь сохранена.";}
 static void seedCached(Context c,String owner,String id,SyncDb db)throws Exception{if(!owner.equals(DownloadSync.owner(c)))return;for(JSONObject p:db.plans(owner,false))if(id.equals(p.optString("id"))&&!p.optBoolean("listed")){PlaylistCache cache=new PlaylistCache(c);JSONObject snapshot=cache.get(id);if(snapshot!=null&&snapshot.optBoolean("cached"))db.snapshot(owner,id,cache.tracks(id));}}
 static void prepare(Context c){new OfflineStore(c).repairKnownCopies();String owner=DownloadSync.owner(c);try(SyncDb db=new SyncDb(c)){for(JSONObject p:db.workPlans(owner)){String id=p.optString("id");try{seedCached(c,owner,id,db);}catch(Exception e){db.status(owner,id,"Не удалось подготовить сохранённый список. Попробуйте проверить очередь ещё раз.");}if(!allowed(c))db.status(owner,id,waitReason(c));}}}
 static int startVisible(Activity a){return startVisible(a,null,true);}
 static int startVisible(Activity a,String selected,boolean refresh){prepare(a);String owner=DownloadSync.owner(a);int queued=0;if(Session.get(a).isEmpty()){try(SyncDb db=new SyncDb(a)){for(JSONObject p:db.workPlans(owner))db.status(owner,p.optString("id"),"Для загрузки войдите в аккаунт SoundCloud. Очередь сохранена.");}return 0;}
  try(SyncDb db=new SyncDb(a)){for(JSONObject p:db.workPlans(owner)){String id=p.optString("id");if(selected!=null&&!selected.equals(id))continue;SyncRequests.put(a,owner,id,refresh||!p.optBoolean("listed"),false,false);db.active(owner,id,true);db.status(owner,id,allowed(a)?"Проверка списка запланирована без уведомления.":waitReason(a));queued++;}}kick(a);retry(a);return queued;
 }
 static boolean connected(Context c){ConnectivityManager cm=c.getSystemService(ConnectivityManager.class);return allowed(cm.getNetworkCapabilities(cm.getActiveNetwork()),false);}
 private static boolean vpn(Context c){ConnectivityManager cm=c.getSystemService(ConnectivityManager.class);NetworkCapabilities caps=cm.getNetworkCapabilities(cm.getActiveNetwork());return caps!=null&&caps.hasTransport(NetworkCapabilities.TRANSPORT_VPN);}
 private static JobInfo.Builder job(Context c,int id){JobInfo.Builder b=new JobInfo.Builder(id,new ComponentName(c,AutoDownloadJob.class)).setPersisted(true);if(wifi(c)&&!SyncRequests.any(c,DownloadSync.owner(c),true)&&!vpn(c)&&Build.VERSION.SDK_INT>=28)b.setRequiredNetwork(new NetworkRequest.Builder().addCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET).addTransportType(NetworkCapabilities.TRANSPORT_WIFI).build());else b.setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY);return b;}
 public static void schedule(Context c){JobScheduler scheduler=c.getSystemService(JobScheduler.class);scheduler.cancel(PERIODIC);try(SyncDb db=new SyncDb(c)){String owner=DownloadSync.owner(c);boolean work=SyncRequests.any(c,owner,false);for(JSONObject plan:db.workPlans(owner))if(db.nextItemRetry(owner,plan.optString("id"))!=Long.MAX_VALUE)work=true;if(!work){scheduler.cancel(ONCE);scheduler.cancel(RETRY);}}}
 public static boolean enabled(Context c,String owner,String id){try(SyncDb db=new SyncDb(c)){for(org.json.JSONObject p:db.plans(owner,false))if(id.equals(p.optString("id")))return p.optBoolean("auto");}return false;}
 public static boolean toggle(Context c,String owner,String id,String title,String kind){boolean value=!enabled(c,owner,id);try(SyncDb db=new SyncDb(c)){db.ensure(owner,id,title,kind);db.auto(owner,id,value);if(value){db.active(owner,id,true);try{seedCached(c,owner,id,db);}catch(Exception ignored){}}if(!value){db.active(owner,id,false);db.cancelPending(owner,id);}db.status(owner,id,value?(allowed(c)?"Очередь подготовлена. Запускаем загрузку…":waitReason(c)):"Автозагрузка выключена.");}AutoDownloadGate.changed(owner,id);if(value){kick(c);retry(c);if(c instanceof Activity)startVisible((Activity)c,id,false);}else {schedule(c);retry(c);}return value;}
 private static boolean sameNetwork(JobInfo a,JobInfo b){return a!=null&&a.getNetworkType()==b.getNetworkType()&&(Build.VERSION.SDK_INT<28||java.util.Objects.equals(a.getRequiredNetwork(),b.getRequiredNetwork()));}
 public static void retry(Context c){try(SyncDb db=new SyncDb(c)){long at=CheckCadence.retryAt(c,db,DownloadSync.owner(c),System.currentTimeMillis());JobScheduler scheduler=c.getSystemService(JobScheduler.class);if(at<=0){scheduler.cancel(RETRY);return;}android.os.PersistableBundle extras=new android.os.PersistableBundle();extras.putLong("at",at);JobInfo wanted=job(c,RETRY).setExtras(extras).setMinimumLatency(Math.max(30000,at-System.currentTimeMillis())).build();JobInfo old=scheduler.getPendingJob(RETRY);if(sameNetwork(old,wanted)&&old.getExtras().getLong("at",Long.MAX_VALUE)<=at)return;scheduler.schedule(wanted);}}
 public static void kick(Context c){schedule(c);try(SyncDb db=new SyncDb(c)){String owner=DownloadSync.owner(c);boolean due=false;for(JSONObject p:db.workPlans(owner))if(CheckCadence.runnable(c,db,owner,p,System.currentTimeMillis())){due=true;break;}if(!due)return;JobScheduler scheduler=c.getSystemService(JobScheduler.class);JobInfo wanted=job(c,ONCE).setMinimumLatency(1000).build();if(!sameNetwork(scheduler.getPendingJob(ONCE),wanted))scheduler.schedule(wanted);}}
}
